x64 <- function(code) with_jax_config("jax_enable_x64", TRUE, code)
arr <- function(x) as.array(x)
# Orthogonality defect max |Q^H Q - I|.
orth_err <- function(q) {
  q <- arr(q)
  max(Mod(Conj(t(q)) %*% q - diag(ncol(q))))
}

test_that("cholesky, cho_factor and cho_solve match the wheel", {
  skip_if_no_backend()
  x64({
    expect_jax_equal(scipy_linalg_cholesky(fx$A), fx$chol_A)
    expect_jax_equal(scipy_linalg_cholesky(fx$A, lower = TRUE), fx$chol_A_lower)
    expect_jax_equal(scipy_linalg_cholesky(fx$Hc), fx$chol_Hc)
    cf <- scipy_linalg_cho_factor(fx$A)
    expect_false(cf[[2L]])
    expect_jax_equal(cf[[1L]], fx$chol_A)
    expect_jax_equal(scipy_linalg_cho_solve(cf, c(1, 2, 3)), fx$cho_solve_b)
    expect_jax_equal(scipy_linalg_cho_solve(scipy_linalg_cho_factor(fx$A, lower = TRUE), fx$B32),
                     fx$cho_solve_B)
    expect_jax_equal(jit(function(a, b) scipy_linalg_cho_solve(list(a, TRUE), b))(
      scipy_linalg_cholesky(fx$A, lower = TRUE), fx$B32), fx$cho_solve_B)
    # Batched 1D right hand sides are deprecated (FutureWarning in JAX).
    cb <- array(rep(fx$chol_A, each = 2L), c(2L, 3L, 3L))
    expect_warning(scipy_linalg_cho_solve(list(cb, FALSE), rbind(1:3, 1:3)), "deprecated")
  })
  expect_identical(dtype(scipy_linalg_cholesky(matrix(c(4L, 2L, 2L, 3L), 2))), "float32")
})

test_that("svd, det and inv match the wheel", {
  skip_if_no_backend()
  x64({
    expect_jax_equal(scipy_linalg_svd(fx$R43, compute_uv = FALSE), fx$svd_R43_s)
    usv <- scipy_linalg_svd(fx$R43, full_matrices = FALSE)
    expect_length(usv, 3L)
    expect_equal(arr(usv[[1L]]) %*% diag(arr(usv[[2L]])) %*% arr(usv[[3L]]), fx$R43,
                 tolerance = 1e-12)
    expect_identical(dim(usv[[1L]]), c(4L, 3L))
    expect_identical(dim(scipy_linalg_svd(fx$R43)[[1L]]), c(4L, 4L))
    expect_jax_equal(scipy_linalg_det(fx$G), fx$det_G)
    expect_jax_equal(scipy_linalg_inv(fx$G), fx$inv_G)
  })
})

test_that("eigh solves standard and generalized problems", {
  skip_if_no_backend()
  x64({
    wv <- scipy_linalg_eigh(fx$A)
    expect_jax_equal(wv[[1L]], fx$eigh_A_w)
    v <- arr(wv[[2L]])
    expect_equal(fx$A %*% v, v %*% diag(fx$eigh_A_w), tolerance = 1e-12)
    expect_jax_equal(scipy_linalg_eigh(fx$Hc, eigvals_only = TRUE), fx$eigh_Hc_w)
    for (type in 1:3) {
      wv <- scipy_linalg_eigh(fx$A, fx$B, type = type)
      expect_jax_equal(wv[[1L]], fx[[paste0("eigh_AB", type, "_w")]])
      expect_jax_equal(wv[[2L]], fx[[paste0("eigh_AB", type, "_v")]], tolerance = 1e-10)
    }
    expect_jax_equal(scipy_linalg_eigh(fx$A, fx$B, eigvals_only = TRUE), fx$eigh_AB1_w)
    # Batched generalized problem.
    ab <- array(c(rbind(c(fx$A), c(fx$A) * 2)), c(2L, 3L, 3L))
    w <- arr(scipy_linalg_eigh(ab, fx$B, eigvals_only = TRUE))
    expect_equal(w[1L, ], fx$eigh_AB1_w, tolerance = 1e-12)
    expect_equal(w[2L, ], 2 * fx$eigh_AB1_w, tolerance = 1e-12)
  })
  expect_error(scipy_linalg_eigh(fx$A, type = 4L), "type must be 1, 2, or 3")
  expect_error(scipy_linalg_eigh(fx$A, eigvals = c(0, 1)), "eigvals=None")
  expect_error(scipy_linalg_eigh(fx$R43), "must have shape \\[\\.\\.\\., n, n\\]")
  expect_error(scipy_linalg_eigh(fx$A, fx$R43), "Argument b")
})

test_that("schur and rsf2csf", {
  skip_if_no_backend()
  x64({
    tz <- scipy_linalg_schur(fx$M)
    t_ <- arr(tz[[1L]])
    z <- arr(tz[[2L]])
    expect_equal(z %*% t_ %*% t(z), fx$M, tolerance = 1e-12)
    expect_lt(orth_err(z), 1e-12)
    expect_equal(t_[3L, 1:2], c(0, 0))
    tzc <- scipy_linalg_schur(fx$M, output = "complex")
    expect_identical(dtype(tzc[[1L]]), "complex128")
    tc <- arr(tzc[[1L]])
    expect_equal(Mod(tc[lower.tri(tc)]), rep(0, 3))
    zc <- arr(tzc[[2L]])
    expect_equal(zc %*% tc %*% Conj(t(zc)), fx$M + 0i, tolerance = 1e-12)
    # rsf2csf of the wheel's real Schur form.
    cs <- scipy_linalg_rsf2csf(fx$schur_M_T, fx$schur_M_Z)
    expect_jax_equal(cs[[1L]], fx$rsf2csf_T)
    expect_jax_equal(cs[[2L]], fx$rsf2csf_Z)
    one <- scipy_linalg_rsf2csf(matrix(2), matrix(1))
    expect_jax_equal(one[[1L]], 2 + 0i)
  })
  expect_error(scipy_linalg_schur(fx$M, output = "foo"), "either 'real' or 'complex'")
  expect_error(scipy_linalg_rsf2csf(fx$M, diag(2)), "shapes must match")
  expect_error(scipy_linalg_rsf2csf(fx$R43, fx$M), "'T' must be square")
})

