test_that("solve and solve_triangular match the wheel", {
  skip_if_no_backend()
  x64({
    expect_jax_equal(scipy_linalg_solve(fx$G, 1:4), fx$solve_gen)
    expect_jax_equal(scipy_linalg_solve(fx$A, fx$B32, assume_a = "pos"), fx$solve_pos)
    expect_jax_equal(scipy_linalg_solve(fx$A, c(1, 2, 3), assume_a = "pos", lower = TRUE),
                     fx$solve_pos_lower)
    ab <- array(c(rbind(c(fx$A), c(fx$B))), c(2L, 3L, 3L))
    expect_jax_equal(scipy_linalg_solve(ab, rbind(c(1, 2, 3), c(3, 2, 1)), assume_a = "pos"),
                     fx$solve_pos_batch)
    expect_jax_equal(jit(function(a, b) scipy_linalg_solve(a, b, assume_a = "pos"))(fx$A, fx$B32),
                     fx$solve_pos)
    # Implicit differentiation through the Cholesky solve.
    f <- function(a) jnp_sum(scipy_linalg_solve(a, c(1, 2, 3), assume_a = "pos")^2)
    check_grad_fd(function(b) jnp_sum(scipy_linalg_solve(fx$A, b, assume_a = "pos")),
                  as_jax(c(1, 2, 3), "float64"))
    g <- arr(grad(f)(as_jax(fx$A)))
    x <- solve(fx$A, c(1, 2, 3))
    lam <- solve(fx$A, 2 * x)
    expect_equal(g, -outer(lam, x), tolerance = 1e-10)
    expect_jax_equal(scipy_linalg_solve_triangular(fx$G, 1:4, lower = TRUE), fx$solve_tri_0)
    expect_jax_equal(scipy_linalg_solve_triangular(fx$G, 1:4, trans = "T", lower = TRUE),
                     fx$solve_tri_T)
    expect_jax_equal(scipy_linalg_solve_triangular(fx$G, 1:4, trans = 2L, lower = TRUE),
                     fx$solve_tri_2)
    expect_jax_equal(scipy_linalg_solve_triangular(fx$M, fx$B32, unit_diagonal = TRUE),
                     fx$solve_tri_unit)
    mb <- vmap(function(b) scipy_linalg_solve_triangular(fx$G, b, lower = TRUE))(rbind(1:4, 1:4))
    expect_equal(arr(mb)[2L, ], fx$solve_tri_0, tolerance = 1e-12)
  })
  expect_error(scipy_linalg_solve(fx$A, 1:3, assume_a = "diagonal"), "Expected assume_a")
  expect_error(scipy_linalg_solve_triangular(fx$A, 1:3, trans = 3L), "Invalid 'trans' value 3")
})

