test_that("expm matches the wheel for every Pade order", {
  skip_if_no_backend()
  x64({
    for (nm in c("small", "mid", "big")) {
      X <- switch(nm, small = fx$M / 100, mid = fx$M / 6, big = fx$M * 3)
      expect_jax_equal(scipy_linalg_expm(X), fx[[paste0("expm_", nm)]])
    }
    expect_jax_equal(scipy_linalg_expm(fx$M), fx$expm_M)
    expect_jax_equal(scipy_linalg_expm(fx$G), fx$expm_G)
    expect_jax_equal(scipy_linalg_expm(fx$G * upper.tri(fx$G, diag = TRUE), upper_triangular = TRUE),
                     fx$expm_upper)
    expect_jax_equal(scipy_linalg_expm(fx$Ab), fx$expm_Ab)
    expect_jax_equal(jit(scipy_linalg_expm)(fx$G), fx$expm_G)
    expect_true(all(is.nan(arr(scipy_linalg_expm(fx$M * 1000, max_squarings = 2L)))))
    g <- grad(function(x) jnp_sum(scipy_linalg_expm(x) * fx$G))(as_jax(fx$G / 2))
    expect_jax_equal(g, fx$grad_expm, tolerance = 1e-10)
    check_grad_fd(function(x) jnp_sum(scipy_linalg_expm(jnp_reshape(x, c(3L, 3L)))),
                  as_jax(c(fx$M) / 3, "float64"))
    stacked <- vmap(scipy_linalg_expm)(fx$Ab)
    expect_jax_equal(stacked, fx$expm_Ab)
  })
  expect_jax_equal(scipy_linalg_expm(fx$M), fx$expm_M_f32, dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(scipy_linalg_expm(fx$G * 2), fx$expm_G_f32, dtype = "float32", tolerance = 1e-5)
  expect_error(scipy_linalg_expm(c(1, 2)), "Expected A to be a \\(batched\\) square matrix")
})

