})

test_that("cg, bicgstab and gmres match the wheel", {
  skip_if_no_backend()
  spd <- fx$A + diag(3)
  gg <- fx$G + 4 * diag(4)
  x64({
    r <- scipy_sparse_linalg_cg(spd, c(1, 2, 3))
    expect_length(r, 2L)
    expect_null(r[[2L]])
    expect_jax_equal(r[[1L]], fx$cg_x, tolerance = 1e-10)
    tr <- scipy_sparse_linalg_cg(function(x) list(jnp_matmul(spd, x[[1L]]), 2 * x[[2L]]),
                                 list(c(1, 2, 3), c(1, 4)))[[1L]]
    expect_equal(c(arr(tr[[1L]]), arr(tr[[2L]])), fx$cg_tree, tolerance = 1e-10)
    expect_jax_equal(scipy_sparse_linalg_cg(spd, c(1, 2, 3), M = diag(1 / diag(spd)))[[1L]],
                     fx$cg_M, tolerance = 1e-10)
    expect_jax_equal(jit(function(b) scipy_sparse_linalg_cg(spd, b)[[1L]])(c(1, 2, 3)), fx$cg_x,
                     tolerance = 1e-10)
    expect_jax_equal(scipy_sparse_linalg_bicgstab(gg, 1:4 + 0)[[1L]], fx$bicgstab_x,
                     tolerance = 1e-10)
    r <- scipy_sparse_linalg_gmres(gg, 1:4 + 0)
    expect_jax_equal(r[[1L]], fx$gmres_x, tolerance = 1e-10)
    expect_jax_equal(r[[2L]], 0L)
    expect_jax_equal(scipy_sparse_linalg_gmres(gg, 1:4 + 0, solve_method = "incremental",
                                               restart = 2L)[[1L]], fx$gmres_inc, tolerance = 1e-10)
    expect_jax_equal(scipy_sparse_linalg_gmres(gg, 1:4 + 0, M = diag(1 / diag(gg)), restart = 3L,
                                               maxiter = 50L)[[1L]], fx$gmres_M, tolerance = 1e-10)
    expect_jax_equal(scipy_sparse_linalg_gmres(fx$Hc, c(1, 1i, 2))[[1L]], fx$gmres_c,
                     tolerance = 1e-10)
    g <- grad(function(b) jnp_sum(scipy_sparse_linalg_cg(spd, b)[[1L]]^2))(as_jax(c(1, 2, 3)))
    expect_jax_equal(g, fx$grad_cg, tolerance = 1e-8)
    g <- grad(function(b) jnp_sum(scipy_sparse_linalg_gmres(gg, b)[[1L]]^2))(as_jax(1:4 + 0))
    expect_jax_equal(g, fx$grad_gmres, tolerance = 1e-8)
    check_grad_fd(function(b) jnp_sum(scipy_sparse_linalg_bicgstab(gg, b)[[1L]]),
                  as_jax(1:4 + 0, "float64"), tolerance = 1e-6)
    xs <- vmap(function(b) scipy_sparse_linalg_cg(spd, b)[[1L]])(rbind(c(1, 2, 3), c(1, 2, 3)))
    expect_equal(arr(xs)[2L, ], fx$cg_x, tolerance = 1e-10)
  })
  expect_error(scipy_sparse_linalg_cg(fx$R43, 1:4), "must be a square matrix")
  expect_error(scipy_sparse_linalg_cg("A", 1:3), "either a function or ndarray")
  expect_error(scipy_sparse_linalg_cg(spd, c(1, 2, 3), x0 = list(1, 2)), "matching tree structure")
  expect_error(scipy_sparse_linalg_cg(spd, c(1, 2, 3), x0 = c(1, 2)), "matching shapes")
  expect_error(scipy_sparse_linalg_gmres(gg, 1:4 + 0, solve_method = "qr"), "invalid solve_method")
})
